import{_ as d,o as a,c as i,a5 as e,j as t,a as o}from"./chunks/framework.BMR-TWOq.js";const n="/RBQ/nightly/images/app/home-motion-more.pc.en.png",s="/RBQ/nightly/images/app/home-drive.pc.en.png",w=JSON.parse('{"title":"Motion commands","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/motion-commands.md","filePath":"manual/gui/motion-commands.md","lastUpdated":1794576042000}'),c={name:"manual/gui/motion-commands.md"};function l(h,r,p,g,m,u){return a(),i("div",null,[...r[0]||(r[0]=[e('<h1 id="motion-commands" tabindex="-1">Motion commands <a class="header-anchor" href="#motion-commands" aria-label="Permalink to &quot;Motion commands&quot;">​</a></h1><p>Motion commands are sent from the motion card on the left of the <a href="/RBQ/nightly/manual/gui/control-home.html">control home</a>. A short tap sends the command immediately; the button that matches the robot&#39;s current gait is highlighted.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Every command here moves the real robot. <strong>Keep people, animals and obstacles at least 2 m away</strong> before pressing, and make sure the robot has completed <strong>Auto Start</strong> and stands on a stable surface.</p></div><h2 id="fixed-buttons" tabindex="-1">Fixed buttons <a class="header-anchor" href="#fixed-buttons" aria-label="Permalink to &quot;Fixed buttons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What the robot does</th></tr></thead><tbody><tr><td><code>SIT</code></td><td>Folds down into the sitting pose. Joystick input is ignored</td></tr><tr><td><code>STAND</code></td><td>From sitting: stands up. From walking or stairs: stops and stands in place</td></tr><tr><td><code>WALK</code></td><td>Starts the walking gait — the joysticks now move the robot</td></tr><tr><td><code>STAIRS</code></td><td>Stair gait: slower steps with the body leaning to the slope</td></tr><tr><td><code>DOCKING</code></td><td>Walks onto the charging dock by itself. The button is only there when docking is available — it disappears while the <code>Dock scan</code> vision toggle is on (the docking overlay on the video takes over). If scanning is turned off in the robot&#39;s settings, the button stays</td></tr></tbody></table><h3 id="sit" tabindex="-1">Sit <a class="header-anchor" href="#sit" aria-label="Permalink to &quot;Sit&quot;">​</a></h3>',6),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/eqR7WaP2d-o",title:"Sit",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"Sit")],-1),t("h3",{id:"stand",tabindex:"-1"},[o("Stand "),t("a",{class:"header-anchor",href:"#stand","aria-label":'Permalink to "Stand"'},"​")],-1),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/6QEGjlFkftI",title:"Stand",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"Stand")],-1),e('<p>While standing, the joysticks adjust the posture instead of moving the robot:</p><table tabindex="0"><thead><tr><th>Joystick</th><th>Input</th><th>Robot action</th></tr></thead><tbody><tr><td>L stick</td><td>Forward / Backward</td><td>Nose up / down</td></tr><tr><td>L stick</td><td>Left / Right</td><td>Roll left / right</td></tr><tr><td>R stick</td><td>Forward / Backward</td><td>Height up / down</td></tr><tr><td>R stick</td><td>Left / Right</td><td>Turn left / right</td></tr></tbody></table><h3 id="walk" tabindex="-1">Walk <a class="header-anchor" href="#walk" aria-label="Permalink to &quot;Walk&quot;">​</a></h3>',3),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/x3d95WWxFF0",title:"Walk",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"Walk")],-1),e('<table tabindex="0"><thead><tr><th>Joystick</th><th>Input</th><th>Robot action</th></tr></thead><tbody><tr><td>L stick</td><td>Forward / Backward</td><td>Go forward / backward</td></tr><tr><td>L stick</td><td>Left / Right</td><td>Go left / right</td></tr><tr><td>R stick</td><td>Forward / Backward</td><td>Pitch forward / backward</td></tr><tr><td>R stick</td><td>Left / Right</td><td>Turn left / right</td></tr></tbody></table><h3 id="stairs" tabindex="-1">Stairs <a class="header-anchor" href="#stairs" aria-label="Permalink to &quot;Stairs&quot;">​</a></h3>',2),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/dq6S16V7oyE",title:"Stairs",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"Stairs")],-1),e('<table tabindex="0"><thead><tr><th>Joystick</th><th>Input</th><th>Robot action</th></tr></thead><tbody><tr><td>L stick</td><td>Forward / Backward</td><td>Go forward / backward</td></tr><tr><td>L stick</td><td>Left / Right</td><td>Go left / right</td></tr><tr><td>R stick</td><td>Left / Right</td><td>Turn left / right</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>On stairs and slopes, keep the approach slow and straight. Do not intervene by hand while the robot is adjusting its posture.</p></div><p>The step-height limit of each gait and the conditions are on <a href="/RBQ/nightly/manual/operation/stairs.html">Stairs and Steps</a>.</p><h2 id="more-motions" tabindex="-1">More motions <a class="header-anchor" href="#more-motions" aria-label="Permalink to &quot;More motions {#more-motions}&quot;">​</a></h2><p>The dashed <strong>Tools</strong> button at the bottom of the card opens the <strong>Select command</strong> grid (<em>Tap to run, then close</em>). Tapping a tile sends that command and closes the grid.</p><p><img src="'+n+'" alt="Select command"></p><p><code>STAIRS</code> and <code>DOCKING</code> are <strong>not</strong> in the grid — they are buttons on the motion card already.</p><p><strong>Model gait</strong></p><table tabindex="0"><thead><tr><th>Tile</th><th>What the robot does</th></tr></thead><tbody><tr><td><code>Wave</code></td><td>Wave gesture</td></tr><tr><td><code>Run</code></td><td>Faster trot. Not shown on wheeled robots</td></tr><tr><td><code>Model Walk</code></td><td>Classic model-based walking gait</td></tr></tbody></table><p><strong>AI motion</strong></p><p>Gaits driven by the robot&#39;s learned (AI) policy. A tap runs the motion immediately.</p><div class="warning custom-block"><p class="custom-block-title">AI motion</p><p>Several AI motions jump, run or balance on two or three legs. Stand the robot up first, keep at least 2 m clear on all sides, and use flat, non-slippery ground.</p></div><table tabindex="0"><thead><tr><th>Tile</th><th>What the robot does</th></tr></thead><tbody><tr><td><code>AI Walk</code></td><td>Walking gait driven by the learned policy</td></tr><tr><td><code>AI Eco</code></td><td>Efficient learned walking gait; <code>Vision Walk</code> switches its terrain-aware policy</td></tr><tr><td><code>AI Vision</code></td><td>Learned walking gait that also uses the cameras to read the terrain</td></tr><tr><td><code>AI Vision Slow</code></td><td>Same as <code>AI Vision</code>, at a slower pace</td></tr><tr><td><code>AI Pronk</code></td><td>Hops with all four legs together</td></tr><tr><td><code>AI Bound</code></td><td>Bounding gait — front and rear leg pairs move together</td></tr><tr><td><code>AI Pace</code></td><td>Pacing gait — legs on the same side move together</td></tr><tr><td><code>AI Run</code></td><td>Fast running gait</td></tr><tr><td><code>AI 2Leg L</code> / <code>AI 2Leg R</code> / <code>AI 2Leg F</code></td><td>Balances on two legs (left, right or front pair)</td></tr><tr><td><code>AI 3Leg HL</code></td><td>Balances on three legs with the rear-left leg lifted</td></tr></tbody></table><p><strong>Precision·Calib</strong></p><table tabindex="0"><thead><tr><th>Tile</th><th>What the robot does</th></tr></thead><tbody><tr><td><code>ZMP Calibration</code></td><td>Balance calibration. Run it while standing. The robot takes one slow step to line up its legs, then calibrates; a popup shows the progress. Keep the area around the robot clear</td></tr><tr><td><code>Robot Check</code></td><td>While standing, tilts the body in roll, then pitch, then yaw (±15°), repeating until you press <code>STAND</code></td></tr></tbody></table><p><strong>Position control</strong></p><p>Amber tiles that force the robot&#39;s posture or open manual recovery.</p><div class="warning custom-block"><p class="custom-block-title">Position control</p><p>Position control changes posture with no trajectory. Use it <strong>only on flat ground with the robot on the floor</strong>. It exists for cases where the normal recovery does not work.</p></div><table tabindex="0"><thead><tr><th>Tile</th><th>What the robot does</th></tr></thead><tbody><tr><td><code>Manual Recovery</code></td><td>Opens the <strong>Manual recovery</strong> panel in the same window — see below</td></tr><tr><td><code>Lock Joints</code></td><td>Holds the current pose</td></tr><tr><td><code>Position Sit</code></td><td>Forces the sitting pose with no trajectory</td></tr><tr><td><code>Position Stand</code></td><td>Forces the standing pose with no trajectory</td></tr></tbody></table><p><strong>Manual recovery</strong> is for a fallen robot that <code>STAND</code> and <code>WALK</code> do not recover: you lock and jog its joints one by one. The commands get no reply, so check the result in the joint angles and the 3D view beside the leg cards. ✕ returns to the grid.</p><ul><li><code>Clear errors</code> — clears the errors and moves the robot to the recovery ready pose.</li><li><code>Auto Recovery (hold)</code> — runs the fall recovery motion. Hold the button until it fires (about 0.6 s); releasing it earlier cancels.</li><li><strong>Static motion</strong> — <code>POS STAND</code>, <code>POS SIT</code> and <code>LOCK</code> force a pose with no trajectory; <code>LOCK</code> holds the current pose. Each runs only when you hold it, like <code>Auto Recovery</code>.</li><li>One card per leg (FL, FR, RL, RR) with three joints each (<code>J0 Roll</code>, <code>J1 Hip</code>, <code>J2 Knee</code> …). Each joint shows <code>Locked</code> or <code>Unlocked</code> and its angle. Tap a joint to lock or unlock it. Hold <code>−</code> or <code>+</code> to jog a locked joint — the joint moves while you hold; the buttons are disabled while it is unlocked. An unlocked joint is not powered.</li><li><code>⚠ Telemetry lost</code> appears next to the hint while the app is not receiving the robot&#39;s telemetry.</li></ul><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#motion">Developer mode</a>.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">Docking</p><p>During docking the robot moves on its own. Do not push or steer it, and make sure the dock is placed correctly and powered. The robot stops and starts charging once it is on the dock.</p></div><h2 id="drive-parameters" tabindex="-1">Drive parameters <a class="header-anchor" href="#drive-parameters" aria-label="Permalink to &quot;Drive parameters {#drive-parameters}&quot;">​</a></h2><p>Tap <strong>Drive</strong> in the tool buttons next to the left joystick to open the <strong>Drive parameters</strong> popover.</p><p><img src="'+s+'" alt="Drive parameters"></p><table tabindex="0"><thead><tr><th>Control</th><th>Range</th><th>Effect</th></tr></thead><tbody><tr><td><code>Vision Walk</code></td><td>on / off</td><td>Uses the camera-assisted walking policy while in <code>WALK</code> or <code>AI Eco</code>. Switching it while walking changes the policy immediately</td></tr><tr><td><code>Max Speed</code></td><td>0.50 – 2.50 m/s</td><td>Upper limit of the walking speed the joystick can command</td></tr><tr><td><code>Body Height</code></td><td>−0.25 – +0.10 m</td><td>Standing height offset relative to the default</td></tr><tr><td><code>Body Tilt</code></td><td>−25° – +25°</td><td>Fixed pitch of the body while walking</td></tr><tr><td><strong>Reset to default</strong></td><td>—</td><td>Restores speed 1.0 m/s, height 0 and tilt 0</td></tr></tbody></table><p>Slider values are sent to the robot when you release the slider, not while dragging.</p>',28),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/2DynPHB6U64",title:"Drive parameters",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"Drive parameters")],-1),t("blockquote",null,[t("p",null,[t("strong",null,"What developer mode adds here"),o(" is collected on "),t("a",{href:"/RBQ/nightly/manual/gui/developer-mode.html#control-home"},"Developer mode"),o(".")])],-1)])])}const y=d(c,[["render",l]]);export{w as __pageData,y as default};
